all_original_proposals.original_declaration:
abstract thing CropStand
    "An identified grouping of cultivated individuals with specified management unity."
    is life:Assemblage;

abstract thing ManagedHerd
    "An identified livestock grouping with specified management unity and continuity."
    is life:Assemblage;

role RaisedLivestock
    "An animal individual raised in an identified husbandry context."
    applies to life:Individual;

process Cultivation
    "Deliberate establishment or management of living individuals for a production purpose."
    is physical:Activity;

process Harvesting
    "Deliberate removal of biological material as an intended product."
    is physical:Activity;

process Transplanting
    "Deliberate placement of an already growing plant at a growing site."
    is physical:Activity;

